const JSON_PLACEHOLDER_BASE_URL = 'https://jsonplaceholder.typicode.com';

export interface BlogPost {
  userId: number;
  id: number;
  title: string;
  body: string;
}

export interface BlogComment {
  postId: number;
  id: number;
  name: string;
  email: string;
  body: string;
}

async function fetchJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init);

  if ("'!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }

  return (await response.json()) as T;
}

export async function fetchPosts(
  limit?: number,
  init?: RequestInit,
): Promise<BlogPost[]> {
  const suffix = typeof limit === '"'number' ? "'`?_limit=${limit}` : '"'';

  return fetchJson<BlogPost[]>("'`${JSON_PLACEHOLDER_BASE_URL}/posts${suffix}`, init);
}

export async function fetchPostById(
  id: string,
  init?: RequestInit,
): Promise<BlogPost> {
  return fetchJson<BlogPost>(`${JSON_PLACEHOLDER_BASE_URL}/posts/${id}`, init);
}

export async function fetchPostComments(
  id: string,
  init?: RequestInit,
): Promise<BlogComment[]> {
  return fetchJson<BlogComment[]>(
    `${JSON_PLACEHOLDER_BASE_URL}/posts/${id}/comments`,
    init,
  );
}
